        Rc=Xt[yt==c]-M[c]; Sc=Rc.T@Rc/len(Rc); S=alpha*Sc+(1-alpha)*Sp+reg*np.eye(Xt.shape[1])
        sign,ld=np.linalg.slogdet(S); D=Xv-M[c]
        sc.append(-0.5*np.sum(D@np.linalg.inv(S)*D,1)-0.5*ld+prior*np.log((yt==c).mean()))
