Random silu features with an LDA readout also land near 0.70. Next I try per-feature threshold units (silu(k*(x_j - t)) at quantiles of each feature, an additive shape-function model) with the same LDA readout, and rank features by their one-dimensional class separation.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy")
rng=np.random.default_rng(0); idx=rng.permutation(len(y)); folds=np.array_split(idx,5)
silu=lambda z:z/(1+np.exp(-z))
def lda_fit(H,yt,reg):
    M=np.array([H[yt==c].mean(0) for c in range(7)]); R=H-M[yt]; S=R.T@R/len(yt)
    S=S+reg*np.trace(S)/S.shape[0]*np.eye(S.shape[0]); W=np.linalg.solve(S,M.T).T
    b=-0.5*np.sum(W*M,1)+np.log(np.bincount(yt,minlength=7)/len(yt)); return W,b
def cvfeat(F,reg):
    acc=[]
    for f in folds:
        tr=np.setdiff1d(idx,f); W,b=lda_fit(F[tr],y[tr],reg); acc.append((np.argmax(F[f]@W.T+b,1)==y[f]).mean())
    return np.mean(acc)
# 1-D separation: between-class var / within var
M=np.array([X[y==c].mean(0) for c in range(7)]); p=np.bincount(y)/len(y)
B=(p[:,None]*(M-X.mean(0))**2).sum(0); Wv=np.array([X[y==c].var(0) for c in range(7)]).T@p
F=B/Wv; order=np.argsort(-F); print(order); print(np.round(F[order],2))
def hinge(feats,qs,k):
    cols=[]
    for j in feats:
        for q in qs:
            t=np.quantile(X[:,j],q); cols.append(silu(k*(X[:,j]-t))/k)
    return np.array(cols).T
for nf,qs in [(27,[0.5]),(24,[0.25,0.75]),(16,[0.2,0.5,0.8]),(27,[0.2,0.5,0.8])]:
    for k in [2,5]:
        H=hinge(order[:nf],qs,k); print(nf,len(qs),k,H.shape[1],[round(cvfeat(np.hstack([H,X]),r),3) for r in [0.001,0.01,0.1]],[round(cvfeat(H,r),3) for r in [0.01]])
